import hashlib
import hmac
import os
import time
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import secrets
import base64

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', secrets.token_hex(32))
DB_PATH = '/tmp/tokens.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.execute('''CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY,
            username TEXT UNIQUE NOT NULL,
            api_key_hash TEXT NOT NULL,
            role TEXT NOT NULL DEFAULT 'user'
        )''')
        g.db.execute('''CREATE TABLE IF NOT EXISTS sessions (
            token TEXT PRIMARY KEY,
            user_id INTEGER NOT NULL,
            expires_at REAL NOT NULL
        )''')
        g.db.commit()
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def generate_api_token(user_id, expires_in=3600):
    """Generate a signed API token."""
    timestamp = int(time.time())
    expiry = timestamp + expires_in
    payload = f"{user_id}:{expiry}"
    signature = hmac.new_hmac(app.config['SECRET_KEY'], payload)
    token = base64.urlsafe_b64encode(f"{payload}:{signature}".encode()).decode()
    return token

def hmac_sign(key, message):
    """Create HMAC-SHA256 signature."""
    return hmac.new(key.encode('utf-8'), message.encode('utf-8'), hashlib.sha256).hexdigest()

def constant_time_compare(val1, val2):
    """Compare two strings in constant time to prevent timing attacks.

    Uses XOR-based comparison with accumulator to avoid
    short-circuit evaluation.
    """
    if len(val1) != len(val2):
        # Still do work to avoid length-based timing leak
        val2 = val2 + '\x00' * (len(val1) - len(val2)) if len(val1) > len(val2) else val2[:len(val1)]

    result = 0
    for x, y in zip(val1, val2):
        result |= ord(x) ^ ord(y)
    return result == 0

def verify_token(token_string):
    """Verify and decode an API token."""
    try:
        decoded = base64.urlsafe_b64decode(token_string.encode()).decode()
        parts = decoded.split(':')
        if len(parts) != 3:
            return None

        user_id, expiry, provided_sig = parts[0], parts[1], parts[2]

        # Check expiration
        if int(expiry) < int(time.time()):
            return None

        # Reconstruct expected signature
        payload = f"{user_id}:{expiry}"
        expected_sig = hmac_sign(app.config['SECRET_KEY'], payload)

        # Constant-time comparison to prevent timing attacks
        if constant_time_compare(provided_sig, expected_sig):
            return int(user_id)
        return None
    except Exception:
        return None

def verify_api_key(api_key):
    """Verify API key against stored hash."""
    db = get_db()
    key_hash = hashlib.sha256(api_key.encode()).hexdigest()
    cursor = db.execute('SELECT id, role FROM users WHERE api_key_hash = ?', (key_hash,))
    row = cursor.fetchone()
    if row:
        return {'user_id': row[0], 'role': row[1]}
    return None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')

        if auth_header.startswith('Bearer '):
            token = auth_header[7:]
            user_id = verify_token(token)
            if user_id is not None:
                g.current_user_id = user_id
                return f(*args, **kwargs)

        elif auth_header.startswith('ApiKey '):
            api_key = auth_header[7:]
            result = verify_api_key(api_key)
            if result:
                g.current_user_id = result['user_id']
                g.current_role = result['role']
                return f(*args, **kwargs)

        return jsonify({'error': 'Unauthorized'}), 401
    return decorated

def require_admin(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if getattr(g, 'current_role', 'user') != 'admin':
            return jsonify({'error': 'Forbidden'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Username required'}), 400

    username = data['username']
    if not username.isalnum() or len(username) > 32:
        return jsonify({'error': 'Invalid username'}), 400

    api_key = secrets.token_hex(32)
    key_hash = hashlib.sha256(api_key.encode()).hexdigest()

    db = get_db()
    try:
        db.execute('INSERT INTO users (username, api_key_hash, role) VALUES (?, ?, ?)',
                   (username, key_hash, 'user'))
        db.commit()
        return jsonify({'api_key': api_key, 'username': username}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username taken'}), 409

@app.route('/api/token', methods=['POST'])
@require_auth
def get_token():
    """Exchange API key for a short-lived token."""
    user_id = g.current_user_id
    timestamp = int(time.time())
    expiry = timestamp + 3600
    payload = f"{user_id}:{expiry}"
    signature = hmac_sign(app.config['SECRET_KEY'], payload)
    token = base64.urlsafe_b64encode(f"{payload}:{signature}".encode()).decode()
    return jsonify({'token': token, 'expires_in': 3600})

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    db = get_db()
    cursor = db.execute('SELECT username, role FROM users WHERE id = ?', (g.current_user_id,))
    row = cursor.fetchone()
    if row:
        return jsonify({'username': row[0], 'role': row[1]})
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_admin
def list_users():
    db = get_db()
    cursor = db.execute('SELECT id, username, role FROM users')
    users = [{'id': r[0], 'username': r[1], 'role': r[2]} for r in cursor.fetchall()]
    return jsonify({'users': users})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
